#pragma once
#include "PresetSaveMenu.h"
#include "PackBrowser.h"
#include <iostream>
static int presetSaveChecks(){
 using namespace juce;using namespace noctrl;auto fail=[](const char* reason){std::cerr<<"PRESET SAVE FAIL: "<<reason<<"\n";return 240;};auto owner=std::make_unique<SynthProcessor>();auto& processor=*owner;processor.loadPreset(0);
 auto menu=presetSaveMenu(processor);PopupMenu::MenuItemIterator empty(menu);if(!empty.next()||empty.getItem().text!="Create new preset"||!empty.getItem().isEnabled||!empty.next()||empty.getItem().text!="Overwrite preset"||empty.getItem().isEnabled)return fail("menu with unsaved sound");
 auto root=File::getCurrentWorkingDirectory().getChildFile("Tests/PresetSave").getNonexistentSibling();PresetLibrary library(root);String packId;if(library.createPack("Own Sounds","Artist","",packId).failed())return fail("pack fixture");PresetMetadata metadata;metadata.name="Heroic Horns";metadata.author="Artist";metadata.description="Original description";processor.set("osc1fine",12);MemoryBlock state;processor.getStateInformation(state);File saved;if(library.savePreset(packId,metadata,state,saved).failed())return fail("new preset");MemoryBlock first;saved.loadFileAsData(first);processor.setStateInformation(first.getData(),(int)first.getSize());if(PresetLibrary::currentPresetFile(processor)!=saved||!PresetLibrary::canOverwriteCurrent(processor))return fail("saved file tracking");
 auto enabled=presetSaveMenu(processor);PopupMenu::MenuItemIterator ready(enabled);ready.next();if(!ready.next()||!ready.getItem().isEnabled)return fail("overwrite enabled");
 processor.set("osc1fine",37);{PackBrowser browser(processor);if(browser.overwriteCurrent().failed())return fail("overwrite current action");}auto files=File(packId).findChildFiles(File::findFiles,false,"*.ncsynth");if(files.size()!=1)return fail("overwrite created a duplicate");MemoryBlock updated;saved.loadFileAsData(updated);if(updated==first)return fail("unchanged sound file");processor.loadPreset(0);if(PresetLibrary::canOverwriteCurrent(processor))return fail("Init retained old target");processor.setStateInformation(updated.getData(),(int)updated.getSize());if(std::abs(processor.value("osc1fine")-37)>.001f||PresetLibrary::currentPresetFile(processor)!=saved)return fail("overwritten sound and path recall");auto restored=PresetMetadata::fromJson(JSON::parse(processor.state.state.getProperty("libraryMetadata").toString()));if(restored.author!="Artist"||restored.description!=metadata.description)return fail("metadata preservation");
 File duplicate;processor.getStateInformation(state);if(library.savePreset(packId,metadata,state,duplicate).failed()||duplicate==saved)return fail("new preset overwrote original");MemoryBlock copy;duplicate.loadFileAsData(copy);processor.setStateInformation(copy.getData(),(int)copy.getSize());if(PresetLibrary::currentPresetFile(processor)!=duplicate)return fail("new preset has old overwrite target");
 MemoryBlock bad("invalid",7);if(library.overwritePreset(saved,metadata,bad).wasOk())return fail("invalid state accepted");MemoryBlock after;saved.loadFileAsData(after);if(after!=updated)return fail("failed overwrite changed original");auto foreign=root.getChildFile("Foreign.SerumPreset");foreign.replaceWithText("Original foreign preset");processor.state.state.setProperty("currentPresetFile",foreign.getFullPathName(),nullptr);if(PresetLibrary::canOverwriteCurrent(processor)||library.overwritePreset(foreign,metadata,state).wasOk())return fail("foreign format overwrite");
 std::unique_ptr<AudioProcessorEditor> editor(processor.createEditor());bool button=false;for(auto* child:editor->getChildren())if(child->getComponentID()=="preset-save-menu")button=true;if(!button)return fail("header menu button");
 std::cout<<"PASS: two header save options, disabled overwrite for unsaved/foreign sounds, new file duplication, overwrite current sound without duplicates, metadata and destination recall, Init target reset and failed-write preservation.\n";return 0;
}
